const e={id:"connect-architecture-fundamentals",track:"amazon-connect",code:"AWS",title:"Architecture Fundamentals",provider:"Amazon Web Services",level:"Fundamentals",category:"Foundations",description:"Create an instance and navigate the admin workspace, then build the foundation: hours of operation, queues, routing profiles, users, flows, and reports.",examFormat:"23 topics · ~29 min · 13 review questions",sourceFiles:["conne/AMAZON CONNECT ARCHITECTURE FUNDAMENTALS.txt"],modules:[{id:"connect-architecture-fundamentals-t1",number:1,title:"Creating an Amazon Connect Instance",shortTitle:"Creating an Amazon Connect Instance",summary:"The first step in setting up an Amazon Connect contact center is to create a virtual contact center instance.",duration:"~3 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t1-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"The first step in setting up an Amazon Connect contact center is to create a virtual contact center instance."},{type:"p",text:"Each instance will contain all the resources and settings related to your contact center. This includes phone numbers, user accounts, routing profiles, queues, flows, analytics, and security configurations. Amazon Connect is a self-contained contact center environment that can be customized to meet your specific business requirements."},{type:"p",text:"Before you begin the setup process, it is important to understand that your instance choices will determine the functionality and integration capabilities with other AWS services. Throughout this section, you will learn best practices for instance creation and configuration. The goal is to make sure your contact center is optimized for reliability, security, and scalability from the start."}]},{id:"connect-architecture-fundamentals-t1-s2",eyebrow:null,duration:null,title:"Things to know before you begin",blocks:[{type:"p",text:"Review the following checklist to make sure you have the necessary knowledge before you begin creating an Amazon Connect instance:"},{type:"p",text:"When you sign up for Amazon Web Services (AWS), your AWS account is automatically signed up for all services in AWS, including Amazon Connect. You are charged only for the services you use. To create an AWS account, see How Do I Create and Activate an AWS Account?"},{type:"p",text:"To create an instance, you will need the AmazonConnect_FullAccess policy permissions granted. For more information, see AmazonConnect_FullAccess."},{type:"p",text:"You will need to know the minimum AWS Identity and Access Management (IAM) permissions required to create an instance. For more information, see Required Permissions for Using Custom IAM Policies to Manage Access to the Amazon Connect Console."},{type:"p",text:"Amazon Connect is not available to customers in India using Amazon Web Services India Private Limited (AWS India), which is an affiliate of AWS based in India. You will receive an error message if you try to create an instance in Amazon Connect."},{type:"p",text:"When you create an instance, you must decide how you want to manage users. You can't change the identity management option after you create the instance. For more information, see Plan Your Identity Management in Amazon Connect."}]},{id:"connect-architecture-fundamentals-t1-s3",eyebrow:null,duration:null,title:"Accessing Amazon Connect in the AWS Console",blocks:[{type:"p",text:"To begin setting up an Amazon Connect instance, access the service through the AWS Management Console as follows:"},{type:"ul",items:["Log in to the console.","In the search box, enter amazon connect, and then choose Amazon Connect from the search results.","Searching for Amazon Connect in the AWS Console."]}]},{id:"connect-architecture-fundamentals-t1-s4",eyebrow:null,duration:null,title:"Create an instance",blocks:[{type:"p",text:"To begin the instance creation process, choose Add an instance to get started."},{type:"p",text:"Amazon Connect instances page in the AWS Console."}]},{id:"connect-architecture-fundamentals-t1-s5",eyebrow:null,duration:null,title:"Setting up an Amazon Connect instance",blocks:[{type:"p",text:"The following five configuration steps combine detailed instructions and general overviews to guide you through establishing your contact center."}]},{id:"connect-architecture-fundamentals-t1-s6",eyebrow:null,duration:null,title:"Step 4: Set storage",blocks:[{type:"h",level:4,text:"Step 5: Review your options"},{type:"p",text:"Wait for your instance to be setup"},{type:"p",text:"It will take a few minutes for the instance to be created and ready for use."},{type:"p",text:"Do not close or refresh the page while the instance is being created!"},{type:"p",text:"Amazon Connect instance is being setup."}]},{id:"connect-architecture-fundamentals-t1-s7",eyebrow:null,duration:null,title:"Your instance has been created",blocks:[{type:"p",text:"Choose Get started to access your instance."},{type:"p",text:"If you chose to manage your users directly within Amazon Connect or through an AWS Directory Service directory, you can access the instance using its access URL. If you chose to manage your users through SAML-based authentication, you can access the instance using the IdP."},{type:"p",text:"Amazon Connect instance has been created."}]},{id:"connect-architecture-fundamentals-t1-s8",eyebrow:null,duration:null,title:"Welcome to Amazon Connect",blocks:[{type:"p",text:"You have now accessed your Amazon Connect instance."},{type:"p",text:"Choose Skip for now, to go to the Home page and Configuration guide."},{type:"p",text:"Welcome to Amazon Connect screen."},{type:"p",text:"You are now ready to start learning about the Amazon Connect Admin Workspace and the first-time setup procedures."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t2",number:2,title:"Navigating the Amazon Connect Admin Workspace",shortTitle:"Navigating the Amazon Connect Admin Workspace",summary:"The Admin Workspace is your central hub for managing all aspects of your contact center. You can configure agent settings, design flows, monitor…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t2-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"The Admin Workspace is your central hub for managing all aspects of your contact center. You can configure agent settings, design flows, monitor performance metrics, and customize user permissions."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t3",number:3,title:"Setting up for the first time",shortTitle:"Setting up for the first time",summary:"Select each of the following setup tasks as you complete them:",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t3-s1",eyebrow:null,duration:null,title:"Checklist for first-time setup",blocks:[{type:"p",text:"Select each of the following setup tasks as you complete them:"},{type:"p",text:"Log in to your instance as follows:"},{type:"ul",items:["Navigate to the login page for Amazon Connect at","https://<your-instance>.my.connect.com."]},{type:"p",text:"Log in with the administrator credentials you created previously."},{type:"p",text:"Claim a phone number as follows:"},{type:"ul",items:["In the navigation menu, choose Channels and then choose Phone numbers.","To acquire a dedicated telephone number for voice calls, choose Claim a number.","You can choose from available local or toll-free numbers.","Associate the number with the Sample Inbound Flow (first contact experience) from the list of available inbound flows.","Choose Save.","Test your setup as follows:","To verify basic functionality, call the number you claimed.","To confirm your setup works, listen to the default greeting."]},{type:"p",text:"These steps verify basic inbound call functionality for the Amazon Connect instance. There are additional steps that must be completed before the Amazon Connect instance is ready for real-world use."},{type:"callout",variant:"key",title:"Tip",body:["Just as activating a new smartphone requires initial setup steps before placing calls. Finishing this checklist verifies your Amazon Connect environment is correctly configured and ready for use."]}]},{id:"connect-architecture-fundamentals-t3-s2",eyebrow:null,duration:null,title:"Additional setup steps",blocks:[{type:"p",text:"After claiming a phone number, follow these steps to guide you through the basics of configuring Amazon Connect for your business:"},{type:"steps",items:[{title:"Set hours of operation",text:"Hours of operation define when Amazon Connect resources, such as queues, are available and can be referenced in flows."},{title:"Create queues",text:"Queues allow contacts to be routed to the most suitable agents to service them."},{title:"Create prompts",text:"Prompts are media that can be used to play back audio to customer or agent contact flows."},{title:"Create flows",text:"Flows, similar to an interactive voice response (IVR), define the customer's experience when they contact you."},{title:"Create routing profiles",text:"A routing profile is a collection of queues an agent services contact from. Routing profiles enable agents to service multiple queues with the proper priority."},{title:"Configure users",text:"User management enables adding, managing, and deleting users. User-specific settings, such as routing profiles and permissions, can be assigned after the users are created."}]},{type:"p",text:"Some of these steps will be covered in greater detail later in the course. However, not all these steps need to be completed. For example, you only need to create prompts if you are not using text-to-speech (TTS) technology."},{type:"p",text:"When these components are correctly set up, your Amazon Connect instance is prepared to receive and process incoming voice calls."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t4",number:4,title:"Knowledge Check",shortTitle:"Knowledge Check",summary:"Course content.",duration:"~2 min",lede:null,objectives:[],sections:[],reviewQuestions:[{id:"connect-architecture-fundamentals-t4-q1",question:"A financial services company wants to set up a new cloud-based contact center using Amazon Connect. Which setting CANNOT be changed after the instance is created?",options:[{id:"A",text:"Identity management"},{id:"B",text:"Telephony options"},{id:"C",text:"Add administrator"},{id:"D",text:"Data storage"}],correctOptionId:"A",rationale:"This setting can be changed after instance creation."},{id:"connect-architecture-fundamentals-t4-q2",question:"An IT administrator needs to setup a newly created Amazon Connect instance. Which section of the Amazon Connect Admin Workspace provides access to contact center configuration options such as reports and performance metrics?",options:[{id:"A",text:"AWS Management Console"},{id:"B",text:"Navigation menu"},{id:"C",text:"Contact Control Panel (CCP)"},{id:"D",text:"Agent workspace"}],correctOptionId:"B",rationale:"Although Amazon Connect options can be configured in the AWS Management Console, the question asks specifically about the Amazon Connect Admin Workspace."},{id:"connect-architecture-fundamentals-t4-q3",question:"A retail company has created a new Amazon Connect instance. The contact center manager asks which essential first-time setup steps must be completed before agents can start accepting customer calls. Which sequence of actions is CORRECT?",options:[{id:"A",text:"First, create hours of operation, then create queues, routing profiles, and users."},{id:"B",text:"First, create security profiles, then create users and routing profiles, and finally claim a phone number."},{id:"C",text:"First, create queues, then create routing profiles and users, and finally set up contact flows."},{id:"D",text:"First, create users, then claim a phone number, create contact flows, and finally set up quick connects."}],correctOptionId:"A",rationale:"Routing profiles depend on queues, but queues depend on hours of operation, which is missing from this sequence."}]},{id:"connect-architecture-fundamentals-t5",number:5,title:"Summary",shortTitle:"Summary",summary:"In this section, you learned how Amazon Connect streamlines the complex process of establishing a contact center. It does this by providing a…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t5-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"In this section, you learned how Amazon Connect streamlines the complex process of establishing a contact center. It does this by providing a user-friendly, cloud-based contact center service that requires minimal technical expertise to configure and deploy. With your instance now created, you are ready to move forward with customizing your contact center to meet your organization's specific customer service requirements."},{type:"p",text:"In the next section, you will learn about configuring users and queues."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t6",number:6,title:"Introduction to Building Your Contact Center Foundation",shortTitle:"Introduction to Building Your Contact Center…",summary:"Have you ever called a company and been directed to the right department without confusion? That smooth experience does not happen by accident. In…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t6-s1",eyebrow:null,duration:null,title:"Section introduction",blocks:[{type:"p",text:"Have you ever called a company and been directed to the right department without confusion? That smooth experience does not happen by accident. In this section, you will configure your contact center's essential framework by creating organizational structures that connect customers with appropriate agents."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t7",number:7,title:"Determining Hours of Operation",shortTitle:"Determining Hours of Operation",summary:"Hours of operation define when your queues are staffed and can receive contacts.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t7-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Hours of operation define when your queues are staffed and can receive contacts."}]},{id:"connect-architecture-fundamentals-t7-s2",eyebrow:null,duration:null,title:"Administration of hours of operation",blocks:[{type:"p",text:"To learn more about setting up hours of operation on the Amazon Connect console, choose each of the numbered markers."},{type:"callout",variant:"key",title:"Tip",body:["You can create multiple hours of operation for different teams or services."]},{type:"p",text:"For example, your technical support might be available around the clock, while billing support is only available Monday through Friday from 09:00 to 17:00."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t8",number:8,title:"Getting Started with Queues",shortTitle:"Getting Started with Queues",summary:"Queues are virtual waiting lines where contacts wait until an agent is available. Think of queues like different lines at a bank. One line is for…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t8-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Queues are virtual waiting lines where contacts wait until an agent is available. Think of queues like different lines at a bank. One line is for deposits, while another line is for loans, and so on."},{type:"p",text:"Queues enable contacts to be directed to the most appropriate agents. Different priority contacts can be assigned to specific queues, allowing for organizational flexibility. Additionally, you can establish specialized queues that connect customers with agents possessing particular skills or expertise needed to address specific types of inquiries."}]},{id:"connect-architecture-fundamentals-t8-s2",eyebrow:null,duration:null,title:"Creating basic queues",blocks:[{type:"p",text:"Creating a queue in Amazon Connect is typically done by using the Amazon Connect console. In the following demonstration, you will learn the basic steps needed to create a queue."},{type:"h",level:4,text:"Transcript: Creating a Queue in Amazon Connect"},{type:"p",text:"Welcome to this demonstration on creating a queue in Amazon Connect."},{type:"p",text:"First, navigate to the Amazon Connect login page and enter your credentials."},{type:"p",text:"The Home page for the Amazon Connect instance opens."},{type:"p",text:"On the navigation menu, choose Routing, and then choose Queues."},{type:"p",text:"On the Queues page, choose Add queue."},{type:"p",text:"The Add queue page opens to enter your details."},{type:"p",text:"On the Add queue page, add the details for your queue."},{type:"p",text:"When you are finished, choose Save."},{type:"p",text:"The newly created queue is displayed on the Queues page."},{type:"p",text:"In this demonstration, you learned how to create a basic queue."},{type:"p",text:"This concludes the demonstration."}]},{id:"connect-architecture-fundamentals-t8-s3",eyebrow:null,duration:null,title:"Types of queues",blocks:[{type:"p",text:"There are two types of queues as follows:"},{type:"p",text:"Standard queues: Contacts wait in standard queues before they are routed to and accepted by agents."},{type:"p",text:"Agent queues: These queues are created automatically when you add an agent to your contact center. Contacts are routed to agent queues only when explicitly sent there as part of a flow. For example, you might route contacts to a specific agent who's responsible for certain customer issues, such as billing. You might also use agent queues to route contacts to an agent's voicemail."}]},{id:"connect-architecture-fundamentals-t8-s4",eyebrow:null,duration:null,title:"Example of a queue",blocks:[{type:"p",text:"In this example, you can see how various flows and queues interact when directing a contact to agents."}]},{id:"connect-architecture-fundamentals-t8-s5",eyebrow:null,duration:null,title:"Using queues",blocks:[{type:"p",text:"When creating queues, it is important to understand the various ways they can be used for routing customers. The following are some typical options to consider:"},{type:"ul",items:["General or basic queue: is used for handling common inquiries.","Technical support queue: is used for for technical issues requiring specialized knowledge.","Billing or accounts queue: is used for for payment or account-related questions.","Priority queue: is used for high priority customers or urgent issues.","Insider tip: Use descriptive names that reflect the purpose of the queue."]}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t9",number:9,title:"Defining Routing Profiles",shortTitle:"Defining Routing Profiles",summary:"A routing profile is a collection of queues that an agent services contacts from. Routing profiles make it possible for agents to service multiple…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t9-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"A routing profile is a collection of queues that an agent services contacts from. Routing profiles make it possible for agents to service multiple queues in the proper priority order."},{type:"p",text:"A routing profile is like a set of rules that decides the following:"},{type:"ul",items:["Which types of customer communications (voice, chat, email, task) an agent can handle","Which customer queues (waiting lines) the agent is connected to"]}]},{id:"connect-architecture-fundamentals-t9-s2",eyebrow:null,duration:null,title:"Applying routing profiles to agents",blocks:[{type:"p",text:"Imagine a school cafeteria with various lunch lines such as pizzas, sandwiches, and salads. These lines represent Amazon Connect queues for different inquiries. Routing profiles work like instruction cards for cafeteria servers. They specify which lines each server can work at and in which priority order."},{type:"p",text:"These cafeteria instructions mirror how Amazon Connect routing profiles direct customer contacts to qualified agents. The system helps support efficient handling while balancing workloads across the team."}]},{id:"connect-architecture-fundamentals-t9-s3",eyebrow:null,duration:null,title:"Example of a real-world use case",blocks:[{type:"p",text:"Different routing profiles accommodate agent experience levels. Consider the following two types of agents:"},{type:"ul",items:["New agents might only handle chats, and they might handle them one at a time.","Experienced agents might handle one voice call and up to three chats simultaneously."]},{type:"p",text:"You would create different routing profiles for each type to appropriately route customers while considering the experience level of the agent."},{type:"h",level:4,text:"Available settings in a routing profile"},{type:"p",text:"When creating a routing profile, you will need to configure the following settings."},{type:"h",level:4,text:"Channels"},{type:"p",text:"Channels are the various types of communications the agent can handle, such as the following:"}]},{id:"connect-architecture-fundamentals-t9-s4",eyebrow:null,duration:null,title:"Task (work assignment)",blocks:[{type:"h",level:4,text:"Concurrency"},{type:"p",text:"Concurrency determines how many conversations agents can handle simultaneously. For example, agents might manage up to three chat interactions at the same time."},{type:"p",text:"You can also configure whether agents can accept chat requests while actively engaging in phone calls."},{type:"h",level:4,text:"Queues"},{type:"p",text:"Queues determine which contacts connect to specific agents."},{type:"p",text:"You can set priority levels for different queues and implement delay timers that control when contacts from certain queues reach agents."}]},{id:"connect-architecture-fundamentals-t9-s5",eyebrow:null,duration:null,title:"Routing functionality in Amazon Connect",blocks:[{type:"p",text:"Review the following example of how channels can be allocated to various queues for agent routing."},{type:"callout",variant:"key",title:"Tip",body:["Each agent can only have one routing profile assigned at any time."]},{type:"p",text:"To learn more about making routing decisions, choose the START or arrow buttons to display each of the four steps."},{type:"p",text:"The system searches for available agents who meeting the following criteria:"},{type:"ul",items:["They are currently online.","They have a routing profile that includes the Technical Support queue.","They are not at their maximum contact limit."]}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t10",number:10,title:"Creating Users and Security Profiles",shortTitle:"Creating Users and Security Profiles",summary:"Users in Amazon Connect represent your agents, supervisors, and administrators who will handle customer contacts or manage the system. Security…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t10-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Users in Amazon Connect represent your agents, supervisors, and administrators who will handle customer contacts or manage the system. Security profiles determine which actions they can perform."},{type:"h",level:4,text:"Creating an account"},{type:"p",text:"When you add users to Amazon Connect, you can configure them with information appropriate to their roles. For example, you specify their security profile, which indicates the tasks they can perform on the Amazon Connect Admin Workspace."},{type:"p",text:"To learn more about creating user accounts, choose the START or arrow buttons to display each of the three steps."}]},{id:"connect-architecture-fundamentals-t10-s2",eyebrow:null,duration:null,title:"Security profiles",blocks:[{type:"p",text:"A security profile is like an ID badge that grants different access levels. It is a group of permissions that maps to a common role in a contact center. For example, the Agent security profile contains permissions needed to access the CCP."},{type:"p",text:"Security profiles help you manage who can access the Amazon Connect dashboard and CCP and who can perform specific tasks."},{type:"p",text:"Amazon Connect comes with the following preconfigured profiles."},{type:"cards",items:[{title:"Admin",body:"This profile grants full access to all Amazon Connect features."},{title:"Agent",body:"This profile grants the basic access needed to handle customer contacts."},{title:"CallCenterManager",body:"This profile grants the ability to manage users and view reports, but it can't change system settings."},{title:"QualityAnalyst",body:"This profile grants access to view and monitor contacts and create reports."}]}]},{id:"connect-architecture-fundamentals-t10-s3",eyebrow:null,duration:null,title:"Assigning a security profile to a user",blocks:[{type:"p",text:"To learn more about assigning security profiles, choose each of the numbered markers."},{type:"p",text:"Consider the following example. If you wanted Sofía from customer service to handle calls but not change system settings, you would assign her the Agent security profile. If you wanted John to manage teams and view performance but not change system configuration, you would assign him the CallCenterManager profile."},{type:"callout",variant:"key",title:"Tip",body:["Only give users the permissions they need for their role. Do not make everyone an administrator."]}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t11",number:11,title:"Knowledge Check",shortTitle:"Knowledge Check",summary:"Course content.",duration:"~2 min",lede:null,objectives:[],sections:[],reviewQuestions:[{id:"connect-architecture-fundamentals-t11-q1",question:"A financial services company is implementing Amazon Connect for its customer support center. The company has three teams: general inquiry agents, fraud specialists, and supervisors. The company needs to make sure appropriate access controls are in place based on job responsibilities. Which approach for creating and managing user accounts provides the BEST security while meeting operational needs?",options:[{id:"A",text:"Create one security profile with all permissions, and assign it to all users for streamlined administration."},{id:"B",text:"Create individual security profiles for each user with custom permissions based on their specific needs."},{id:"C",text:"Create three security profiles aligned with the job roles (agent, specialist, supervisor), and assign users to the appropriate profile."},{id:"D",text:"Create a single Agent security profile and a single supervisor security profile, and give the supervisor profile to both supervisors and specialists."}],correctOptionId:"C",rationale:"Creating three role-based security profiles (general inquiry agents, fraud specialists, and supervisors) implements the principle of least privilege by giving users only the permissions they need based on their job functions. This approach balances security and operational efficiency by standardizing permissions at the role level while making sure there are appropriate access restrictions. It also streamlines user management because new employees can be assigned to an existing profile instead of requiring custom permissions configuration."},{id:"connect-architecture-fundamentals-t11-q2",question:"A retail company is implementing Amazon Connect for its customer service operations. The company needs to set up a contact center that handles three types of customer inquiries: billing questions, product returns, and new orders. The company has agents with specialized training for each inquiry type and wants to make sure contacts are properly directed. Which queue configuration approach would be MOST effective for this scenario?",options:[{id:"A",text:"Create a single queue, and use a routing profile to distribute contacts based on agent skills."},{id:"B",text:"Create a single queue with priority levels for each inquiry type."},{id:"C",text:"Create three separate queues based on inquiry types, and assign agents to the appropriate routing profiles."},{id:"D",text:"Create three separate queues, and assign all agents to all queues with different priority levels."}],correctOptionId:"C",rationale:"Using a single queue with routing profiles for distribution would not properly direct contacts before they reach agents. In Amazon Connect, queues are the primary mechanism for organizing contacts by type, while routing profiles determine which agents receive contacts from which queues. Without separate queues, proper reporting and management of different inquiry types would be difficult."},{id:"connect-architecture-fundamentals-t11-q3",question:"An insurance company is implementing Amazon Connect and needs to make sure after-hours callers receive appropriate messaging. Which configuration should be created FIRST as part of the initial setup before building the relevant contact flows?",options:[{id:"A",text:"Quick connects"},{id:"B",text:"Agent status"},{id:"C",text:"Security profiles"},{id:"D",text:"Hours of operation"}],correctOptionId:"D",rationale:"Hours of operation must be defined early in the setup process because they're a fundamental building block that contact flows reference to make routing decisions. Administrators can create contact flows that provide appropriate responses based on whether a contact arrives during or outside business hours."}]},{id:"connect-architecture-fundamentals-t12",number:12,title:"Summary",shortTitle:"Summary",summary:"In this lesson, you explored the fundamental practices for effective Amazon Connect administration. You now have the essential knowledge to build…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t12-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"In this lesson, you explored the fundamental practices for effective Amazon Connect administration. You now have the essential knowledge to build a well-organized contact center. This includes setting up secure user accounts and developing strategic queue structures. You also understand how to set appropriate operational hours and implement effective routing profiles. These foundational elements will help ensure your contact center runs efficiently and securely."},{type:"p",text:"In the next section, you will learn about creating contact flows."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t13",number:13,title:"Introduction to Creating Flows",shortTitle:"Introduction to Creating Flows",summary:'Have you ever called a company and were prompted, "Press 1 for sales, press 2 for support." This is an interactive voice response (IVR) system,…',duration:"~2 min",lede:null,objectives:["Identify the different types of flows and their purposes.","Recognize best practices for creating functional contact flows.","Recognize best practices for creating an IVR system for customer interactions.","Recognize best practices for testing and publishing flows to make sure they work correctly."],sections:[{id:"connect-architecture-fundamentals-t13-s1",eyebrow:null,duration:null,title:"Section introduction",blocks:[{type:"p",text:`Have you ever called a company and were prompted, "Press 1 for sales, press 2 for support." This is an interactive voice response (IVR) system, and in Amazon Connect, IVR's are created using contact flows. In this section, you will explore how to build IVR pathways that guide customers through your contact center. Think of flows like the roads and signposts that direct customers to their destinations.`}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t14",number:14,title:"Understanding Flow Types",shortTitle:"Understanding Flow Types",summary:"Flows control the customer experience in your contact center. Amazon Connect provides several types of flows, each built for different purposes.…",duration:"~3 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t14-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Flows control the customer experience in your contact center. Amazon Connect provides several types of flows, each built for different purposes. Each flow type in Amazon Connect contains only the building blocks available for that specific flow type."},{type:"callout",variant:"key",title:"Tip",body:["Make sure you select the correct flow type when creating a new flow. Each flow has blocks specifically available for that flow type."]},{type:"cards",items:[{title:"Inbound flow",body:"These are the primary flows that handle initial customer interactions and are used when a customer initiates a call or chat."},{title:"Campaign flow",body:"These flows are used to manage what the customer experiences during an outbound campaign."},{title:"Customer queue flow",body:"These flows are designed to manage customer queues, such as prioritizing certain customers or routing them based on their needs."},{title:"Customer hold flow",body:"These flows are used to manage what the customer experiences when they are on hold."}]},{type:"p",text:"With this flow, one or more audio prompts can be played to a customer using the Loop prompts block while they wait on hold."},{type:"h",level:4,text:"Customer whisper flow"},{type:"p",text:"This flow is used to manage what the customer experiences as part of an inbound call immediately before being joined with an agent."},{type:"p",text:"The Agent whisper and Customer whisper flows are played to completion, then the agent and customer are joined."},{type:"h",level:4,text:"Outbound whisper flow"},{type:"p",text:"This flow manages what the customer experiences as part of an outbound call before being connected with an agent."},{type:"p",text:"In this flow, the whisper is played to completion to the customer, then the agent and customer are joined. For example, this flow can be used to enable call recordings for outbound calls with the Set recording and analytics behavior block. For more information, see Flow Block in Amazon Connect: Set Recording and Analytics Behavior."},{type:"h",level:4,text:"Agent hold flow"},{type:"p",text:"This flow is used to manage what the agent experiences when on hold with a customer."},{type:"p",text:"With this flow, one or more audio prompts can be played to an agent using the Loop prompts block while the customer is on hold."},{type:"h",level:4,text:"Agent whisper flow"},{type:"p",text:"This flow is used to manage what the agent experiences as part of an inbound call immediately before being joined with a customer."},{type:"p",text:"The Agent whisper and Customer whisper flows are played to completion, then the agent and customer are joined."},{type:"h",level:4,text:"Transfer to agent flow"},{type:"p",text:"This flow is used to manage what the agent experiences when transferring to another agent."},{type:"p",text:"This type of flow is used to tranfer a contact directly to an Agent bypassing waiting in a standard queue. For more information, see Flow Block in Amazon Connect: Transfer to Agent."},{type:"h",level:4,text:"Transfer to queue flow"},{type:"p",text:"This flow is used to manage what the agent experiences when transferring to another queue."},{type:"p",text:"This type of flow transfers contacts to standard queues. A Set working queue block placed earlier in the sequence determines which specific queue receives the incoming contact. This structure ensures proper contact routing and assignment. For more information, see Flow Block in Amazon Connect: Transfer to Queue."},{type:"p",text:"To keep up to date with the flow types available in Amazon Connect, see Choose a Flow Type in the Create a Flow section of the Amazon Connect Administrator Guide."},{type:"callout",variant:"key",title:"Tip",body:["Do not place any sensitive information in a Transfer to agent flow."]},{type:"p",text:"You should never include sensitive information in a Transfer to agent flow for a critical reason. During cold transfers, if the transferring agent disconnects before completion, the flow plays back to the caller instead of the receiving agent. This means any confidential information within the flow would be inadvertently exposed to the customer."}]},{id:"connect-architecture-fundamentals-t14-s2",eyebrow:null,duration:null,title:"Flow relationships",blocks:[{type:"p",text:"The following diagram represents the journey of a contact through an Amazon Connect system."},{type:"p",text:"Starting with Contact enters system at the top, the flow branches based on contact type (Inbound, Outbound, or Transfer). The flow then progresses through various specialized flows, including the Customer queue flow, Agent whisper flow, Customer hold flow, Transfer to agent flow, and Campaign flow."},{type:"p",text:"To illustrate the complete contact routing process from entry to agent connection, all paths eventually converge at Connected to agent."},{type:"p",text:"To learn more about contact flow relationships, choose each of the numbered markers."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t15",number:15,title:"Understanding Flow Designer and Flow Blocks",shortTitle:"Understanding Flow Designer and Flow Blocks",summary:"The starting point for all flows is Flow designer in Amazon Connect. Flow designer is a drag-and-drop work surface you can use to create and…",duration:"~8 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t15-s1",eyebrow:null,duration:null,title:"Flow designer in Amazon Connect",blocks:[{type:"p",text:'The starting point for all flows is Flow designer in Amazon Connect. Flow designer is a drag-and-drop work surface you can use to create and customize customer experiences by linking blocks together. For example, when a customer first enters your contact center, you can ask for some input and then play a prompt, such as "Thank you for calling."'},{type:"p",text:"Amazon Connect flow designer with the Block Library expanded showing the Interact blocks."}]},{id:"connect-architecture-fundamentals-t15-s2",eyebrow:null,duration:null,title:"Flow blocks",blocks:[{type:"p",text:"Flows are built using blocks, which are pre-built components that perform specific actions."},{type:"p",text:"The following are some of the most commonly used flow blocks when building your customer experience journeys."},{type:"cards",items:[{title:"Set logging behavior block",body:"This block enables flow logs so you can track events as contacts interact with flows. For example, you can use this block to create logs that are sent to Amazon CloudWatch."},{title:"Set recording and analytics behavior block",body:"This block includes settings to enable the following:"}]}]},{id:"connect-architecture-fundamentals-t15-s3",eyebrow:null,duration:null,title:"Analytics behaviors for contacts",blocks:[{type:"p",text:"For example, you can use this block to configure only recording the agent protion of the conversation."},{type:"cards",items:[{title:"Set voice block",body:"This block sets the text-to-speech (TTS) language and voice to use for the flow. For example, you can choose any voice available in Amazon Polly."},{title:"Play prompt block",body:'This block plays audio prompts, TTS messages, or chat responses to customers and agents. For example, "Thank you for calling."'},{title:"Get customer input block",body:'This block provides tasks, such as capturing customer information, creating interactive phone menus for customer responses, and routing customers to specific paths within a flow. Examples include "Press or say 1 for sales, press or say 2 for support" or "How can I help you today?"'},{title:"Check contact attributes block",body:"This block provides branching based on the comparison of the value of a contact attribute to a condition. For example, checking if it's a new or returning caller or if the contact type is a chat contact."},{title:"Set working queue block",body:"This block is used for specifying which queue is going to transfer a contact when the Transfer to queue is invoked. For example, routing a contact to the technical support queue."},{title:"Transfer to queue block",body:"This block transfers the current contact to the queue specified in the Set working queue block. For example, transferring to an agent after collecting information."},{title:"Disconnect / hangup block",body:"This block ends the contact. For example, after providing information in a self-service scenario."}]},{type:"callout",variant:"key",title:"Tip",body:["Make sure you review which channels are supported by each flow block in Amazon Connect. Some blocks only support certain channels."]},{type:"h",level:4,text:"Transcript: Creating a Flow in Amazon Connect"},{type:"p",text:"Welcome to this demonstration on creating a flow in Amazon Connect."},{type:"p",text:"You will start by accessing the instance."},{type:"p",text:"Navigate to the Amazon Connect login page, and then enter your credentials."},{type:"p",text:"After you have logged in, the Amazon Connect Home page opens with all the available features and tools."},{type:"p",text:"To access the flow designer, in the navigation menu, choose Routing, and then choose Flows."},{type:"p",text:"To start building the customer experience from scratch, on the Flows page, choose Create flow."},{type:"p",text:"Next, to help with future management, give your flow a descriptive name. Choose Enter a name, and then enter Simple Menu Routing Flow."},{type:"p",text:"It's best practice to document your work. So, at the bottom of the flow designer, choose About this flow to add context."},{type:"p",text:"Now, in the Description field, enter a clear description to explain what this flow does. This helps teammates understand its purpose."},{type:"p",text:"Next, you will add your first interaction block."},{type:"p",text:"In Block Library, choose Interact, and then choose the Play prompt block."},{type:"p",text:"Now, drag the Play prompt block to the canvas. This will be your caller's first experience."},{type:"p",text:"Connect the Entry point block to the Play prompt block by drawing a line between them. This is the caller's entry path."},{type:"p",text:"Next, double-click the Play prompt block to configure it. This is where you will set up your initial greeting."},{type:"p",text:"Choose Text-to-speech or chat text. This will convert your text to a professional voice greeting."},{type:"p",text:"Now, enter the following welcome message: Thank you for calling. Please select from the following options."},{type:"p",text:"To confirm the settings and return to the canvas, choose Save at the bottom of the panel."},{type:"p",text:"Now, in the Block Library, choose Interact, and then choose the Get customer input block. This will create your menu options."},{type:"p",text:"Drag the Get customer input block onto the canvas next to the Play prompt block. Position it for visual flow clarity."},{type:"p",text:"Next, to create a logical call progression, connect the Success path green arrow from the Play prompt block to the Get customer input block."},{type:"p",text:"Then, to configure the options you will present to callers, double-click the Get customer input block."},{type:"p",text:"Choose Text-to-speech or chat. Then, enter Press 1 for Sales, Press 2 for Support, Press 3 for Billing."},{type:"p",text:"To create the first menu choice, choose Add a condition. This enables keypad entry."},{type:"p",text:"For Option, enter 1. This corresponds to the Sales option in your voice prompt."},{type:"p",text:"Choose Add a condition again, and then enter 2. This will be mapped to your Support department."},{type:"p",text:"Next, choose Add a condition once more, and then enter 3 for Billing inquiries."},{type:"p",text:"To apply your menu configuration, choose Save. You have now created a three-option menu for callers."},{type:"p",text:"Notice how the options appear as distinct paths extending from the Get customer input block, and there is one for each choice. Now, you will direct these choices to the right departments."},{type:"p",text:"In the search box in the Block Library, enter set working queue."},{type:"p",text:"Drag three Set working queue blocks onto the canvas next to the Get customer input block."},{type:"p",text:"To configure where sales calls should go, double-click the first Set working queue block."},{type:"p",text:"For Block Name, enter Transfer to Sales. Descriptive labels make troubleshooting less complicated."},{type:"p",text:"On the menu, choose the Sales queue. This is where agents handling sales are waiting."},{type:"p",text:"To complete the configuration of this routing destination, choose Save."},{type:"p",text:"Then, configure the second block. For the block name, enter Transfer to Support, and then choose the Support queue."},{type:"p",text:"Now, configure the third block. To maintain consistency, for the block name, enter Transfer to Billing, and then choose the Billing queue."},{type:"p",text:"To create the path, connect Pressed 1 in the Get customer input block to the Transfer to Sales block."},{type:"p",text:"Then, connect Pressed 2 in the Get customer input block to the Transfer to Support block. Each caller choice must lead somewhere specific."},{type:"p",text:"To complete the three department routing options, connect Pressed 3 in the Get customer input block to the Transfer to Billing block."},{type:"p",text:"Now, you need to handle errors properly. In the search box in the Block Library, enter play prompt."},{type:"p",text:"Drag another Play prompt block onto the canvas. This will handle invalid selections professionally."},{type:"p",text:"Configure this block with the following message: Sorry, that's not a valid selection. Always keep the tone courteous."},{type:"p",text:"To cover all error scenarios, connect the Timeout, Default, and Error paths in the Get customer input block to the Play prompt block."},{type:"p",text:"Then, in the search box in the Block Library, enter disconnect. You need to end calls that don't proceed to a department."},{type:"p",text:"Drag a Disconnect block onto the canvas. This ends the contact gracefully."},{type:"p",text:"Now, connect the Success and Error paths from the Play prompt block to the Disconnect block."},{type:"p",text:"Then, connect the Error paths from all three Set working queue blocks to the Disconnect block for consistency."},{type:"p",text:"In the search box in the Block Library, enter transfer to queue. This actually sends calls to your agents."},{type:"p",text:"Drag a Transfer to queue block onto the canvas. This is the critical block that delivers calls to your teams."},{type:"p",text:"To create the final routing step, connect the Success paths from all three Set working queue blocks to the Transfer to queue block."},{type:"p",text:"Now, drag another Disconnect block to the flow for call completion."},{type:"p",text:"Then, connect both paths from the Transfer to queue block to the new Disconnect block."},{type:"p",text:"Next, save your work. To preserve your flow design, choose Save at the top of the flow designer."},{type:"p",text:"In the Save Flow pop-up box that appears, choose Save to confirm the action. Always confirm important actions."},{type:"p",text:"A success message appears indicating that your flow was saved successfully."},{type:"p",text:"Next, to activate your flow and make it available for use, choose Publish at the top of the flow designer."},{type:"p",text:"In the Publish Simple Menu Routing Flow pop-up box that appears, choose Publish to confirm the action. This moves your flow into production."},{type:"p",text:"An error message appears indicating that there's a problem with the flow. This is helpful for identifying problems before going live."},{type:"p",text:"Identify any blocks with red alert icons. These highlight issues that need to be addressed."},{type:"p",text:"The error indicates that you need to connect all paths. Every possible scenario must have a resolution."},{type:"p",text:"To handle the unconnected Error path from the first Play prompt block, add another Disconnect block."},{type:"p",text:"Now, to resolve the issue, connect the Error path from the first Play prompt block to the new Disconnect block."},{type:"p",text:"Then, choose Publish at the top of the flow designer."},{type:"p",text:"Now, try publishing the connected flow. In the Publish Simple Menu Routing Flow pop-up box that appears, choose Publish. This second confirmation prevents accidental publishing."},{type:"p",text:"Congratulations. A message appears confirming your flow has been published successfully and is ready to use."},{type:"p",text:"Now, associate the flow with a phone number. In the navigation menu, choose Channels, and then choose Phone numbers."},{type:"p",text:"Next, select an existing phone number or claim a new one. This will be your customer-facing contact point."},{type:"p",text:"Scroll to the Contact flow / IVR section."},{type:"p",text:"Then, open the menu, and choose your newly created Simple Menu Routing Flow."},{type:"p",text:"To apply the changes, choose Save. This finalizes the connection between your number and the flow."},{type:"p",text:"Your flow is now associated with the phone number. Callers will experience your carefully designed menu."},{type:"p",text:"This concludes this demonstration on creating an inbound call flow in Amazon Connect."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t16",number:16,title:"Publishing, Testing, and Flow Best Practices",shortTitle:"Publishing, Testing, and Flow Best Practices",summary:"Before making your flow live, make sure to verify and validate the required customer experience.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t16-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Before making your flow live, make sure to verify and validate the required customer experience."},{type:"p",text:"Use the following checklist to guide you as you build your flows and prepare for receiving customer contacts:"},{type:"ul",items:["Choose Create flow in flow designer for the required customer experience.","Enter or verify the following information:"]}]},{id:"connect-architecture-fundamentals-t16-s2",eyebrow:null,duration:null,title:"Flow description (optional): Details about the flow's purpose or functionality",blocks:[{type:"p",text:"Choose Save in the upper-right corner of the flow designer interface."},{type:"p",text:"Choose Publish in the upper-right corner of the flow designer. A success message will appear confirming the flow has been published. After it's published, the flow becomes active and can be used in your contact center."},{type:"p",text:"Verify that your flow is associated with a phone number in the Phone numbers management section. If not, associate your flow with a phone number."},{type:"p",text:"Call the phone number associated with your flow. Navigate through the flow as a customer would. Verify that the flow behaves as expected."},{type:"p",text:"Based on the test results, make the necessary adjustments to your flow. Save, publish, and test again until the flow functions as intended."},{type:"p",text:"To read the list of recommended best practices when you are using and creating flows, see Best Practices for Flows in Amazon Connect in the Amazon Connect Administrator Guide."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t17",number:17,title:"Knowledge Check",shortTitle:"Knowledge Check",summary:"Course content.",duration:"~2 min",lede:null,objectives:[],sections:[],reviewQuestions:[{id:"connect-architecture-fundamentals-t17-q1",question:'A retail company is setting up an Amazon Connect contact center. When customers call, they need to hear a welcome message followed by menu options. If agents are busy, customers should hear music and wait-time announcements. Before connecting to an agent, the customer should hear, "Please hold while we connect you to an agent." Which contact flow types are needed for this basic setup?',options:[{id:"A",text:"Inbound flow, Customer queue flow, Customer whisper flow"},{id:"B",text:"Inbound flow, Transfer to Agent flow, Agent whisper flow"},{id:"C",text:"Campaign flow, Agent hold flow, Transfer to agent flow"},{id:"D",text:"Campaign flow, Agent Hold flow, Transfer to queue flow"}],correctOptionId:"A",rationale:"Campaigns flows are used for outbound campaigns and not used in this type of interaction."},{id:"connect-architecture-fundamentals-t17-q2",question:"A financial services company is building a contact flow to authenticate callers by verifying their account information. Which sequence of Amazon Connect blocks would correctly implement this requirement?",options:[{id:"A",text:"Store customer input, Get customer input, Play prompt, Check contact attributes, Transfer to queue"},{id:"B",text:"Play prompt, Get customer input, Check contact attributes, branch based on result, Transfer to queue or Disconnect"},{id:"C",text:"Store customer input, Get customer input, Play prompt, Transfer to queue"},{id:"D",text:"Set contact attributes, Play prompt, Check contact attributes, Transfer to agent"}],correctOptionId:"B",rationale:"This sequence tries to store input before collecting it and does not include a prompt to explain which information the customer should provide."},{id:"connect-architecture-fundamentals-t17-q3",question:"A company wants to implement a basic interactive voice response (IVR) system in Amazon Connect that asks customers to select between sales, support, and billing departments. Which configuration would create the MOST effective customer experience?",options:[{id:"A",text:"Create a contact flow with three Play prompt blocks in sequence, each announcing a department option and its associated digit. Then, use a Get customer input block configured to accept Dual-Tone Multi-Frequency (DTMF) digits."},{id:"B",text:"Create a contact flow with a single Play prompt block that lists all options, followed by a Get customer input block configured to accept Dual-Tone Multi-Frequency (DTMF) digits, then branch based on the customer's selection."},{id:"C",text:"Create a contact flow with a Set contact attributes block assigning department options, followed by a Check contact attributes block to determine customer department preference."},{id:"D",text:"Create separate contact flows for each department and use a Get customer input block to transfer the customer to the appropriate flow."}],correctOptionId:"B",rationale:"Using three separate prompts is inefficient and confusing. Customers hear each department mentioned individually without seeing all options together. This makes it hard to understand available choices."},{id:"connect-architecture-fundamentals-t17-q4",question:"A contact center manager has created a new Amazon Connect voice flow that routes customers to different departments. What is the MOST effective way to test if the flow works correctly before deploying it to all customers?",options:[{id:"A",text:"Publish the flow and then call the contact center number to test it as a customer."},{id:"B",text:"Use the Amazon Connect save and publish feature without testing because there is no simulation option for voice."},{id:"C",text:"Create a test phone number in Amazon Connect and assign it to the new flow before publishing to the main number."},{id:"D",text:"Export the flow as a JSON file and analyze the code for logical errors."}],correctOptionId:"C",rationale:"Publishing directly to the main phone number without prior testing risks disrupting service for all customers if there are issues with the flow."}]},{id:"connect-architecture-fundamentals-t18",number:18,title:"Summary",shortTitle:"Summary",summary:"In this section, you learned about Amazon Connect flows. You explored how blocks create basic and complex customer journeys. Now you can design,…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t18-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"In this section, you learned about Amazon Connect flows. You explored how blocks create basic and complex customer journeys. Now you can design, test, and publish flows that help customers connect with agents, use self-service options, or wait in queue effectively."},{type:"p",text:"In the next section, you will learn about reporting and its importance."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t19",number:19,title:"Introduction to First Steps with Reporting",shortTitle:"Introduction to First Steps with Reporting",summary:"Have you ever needed to determine if your contact center is meeting performance targets? In this section, you will explore how Amazon Connect…",duration:"~2 min",lede:null,objectives:["Access and navigate standard Amazon Connect reports.","Identify key metrics that measure contact center performance.","Recognize best practices for using reporting data to make informed decisions about your contact center."],sections:[{id:"connect-architecture-fundamentals-t19-s1",eyebrow:null,duration:null,title:"Section introduction",blocks:[{type:"p",text:"Have you ever needed to determine if your contact center is meeting performance targets? In this section, you will explore how Amazon Connect reporting tools provide visibility into contact center operations. Like a car's dashboard displaying speed and fuel level, these reports indicate your contact center's operational efficiency."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t20",number:20,title:"Accessing built-in Reports",shortTitle:"Accessing built-in Reports",summary:"Amazon Connect comes with built-in reports that give you insights into your contact center's performance without any additional setup. These…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t20-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Amazon Connect comes with built-in reports that give you insights into your contact center's performance without any additional setup. These ready-to-use reporting tools provide immediate visibility into key metrics and operational data so you can make informed decisions from day one. The built-in reporting feature of Amazon Connect offers strong analytics for contact center. You can monitor agent performance in real-time, analyze past contact patterns, and check service level adherence all in one place."},{type:"p",text:"To learn how to find reports in Amazon Connect, choose each of the numbered markers."},{type:"p",text:"Amazon Connect Admin Workspace navigation menu showing the Analytics and optimization sub menu."}]},{id:"connect-architecture-fundamentals-t20-s2",eyebrow:null,duration:null,title:"Dashboard and report types",blocks:[{type:"p",text:"Amazon Connect reporting offers various dashboards and report types, each designed to provide specific insights into different aspects of your contact center operations. Understanding the purpose and capabilities of each report type is essential for effectively monitoring performance, identifying trends, and making data-driven decisions."}]},{id:"connect-architecture-fundamentals-t20-s3",eyebrow:null,duration:null,title:"Real-time Metrics report",blocks:[{type:"h",level:4,text:"Historical metrics report"},{type:"p",text:"Pre-built visual tools that display both real-time and historical contact center performance data include the following:"}]},{id:"connect-architecture-fundamentals-t20-s4",eyebrow:null,duration:null,title:"Shareable with individuals or the entire instance",blocks:[{type:"p",text:"You can access these tools by choosing Analytics and optimization, then Dashboards and reports."},{type:"p",text:"Pre-built dashboards for reporting available in Amazon Connect."},{type:"callout",variant:"key",title:"Tip",body:["Think of real-time metrics as a live traffic map showing current conditions, whereas historical metrics are like reviewing footage of past traffic patterns to plan better routes."]}]},{id:"connect-architecture-fundamentals-t20-s5",eyebrow:null,duration:null,title:"Real-time Metrics report",blocks:[{type:"h",level:4,text:"Historical metrics report"},{type:"p",text:"This report provides immediate visibility into current contact center operations with updates every 15 seconds. It makes it possible for you to do the following:"},{type:"ul",items:["Monitor contacts in queue, oldest contact wait time, available agents, and abandonment rate.","Enable immediate operational decision-making.","Identify where long waits might be occurring.","The real-time metrics report can be accessed by choosing Analytics and optimization, then Real-time metrics."]},{type:"h",level:4,text:"Historical metrics report"},{type:"p",text:"This report offers insights into past performance for identifying trends and strategic decision-making. It makes it possible for you to do the following:"},{type:"ul",items:["Configure time periods (hours, days, weeks, or months) up to 30 days.","Customize settings for intervals, groupings, filters, and metrics.","Track metrics like average handle time, abandonment rates, and service level achievements.","Help identify patterns and improvement opportunities.","The historical metrics report can be accessed by choosing Analytics and optimization, then Historical metrics."]}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t21",number:21,title:"Understanding Key Metrics",shortTitle:"Understanding Key Metrics",summary:"There are specific metrics that are important for your contact center performance monitoring and operations. These key performance indicators…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t21-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"There are specific metrics that are important for your contact center performance monitoring and operations. These key performance indicators (KPIs) serve as the foundation for evaluating efficiency, agent productivity, customer satisfaction, and overall contact center health. By learning these essential metrics, you can identify operational bottlenecks, recognize emerging patterns, and benchmark your performance against industry standards."},{type:"p",text:"To explore some key metrics that tell you how your contact center is performing, choose each of the following flashcards."}]},{id:"connect-architecture-fundamentals-t21-s2",eyebrow:null,duration:null,title:"Why these metrics matter",blocks:[{type:"p",text:"It is important to monitor these key metrics in your contact center for the following reasons:"},{type:"h",level:4,text:"Service level: Shows if customers are being served promptly"},{type:"p",text:"Example: 80 percent of calls answered in 30 seconds"},{type:"ul",items:["Average handle time (AHT): Indicates agent efficiency and contact complexity","Example: Average handle time: 5 minutes 23 seconds"]},{type:"cards",items:[{title:"Abandonment rate: High rates suggest customers are waiting too long",body:"Example: 5 percent abandonment rate"},{title:"Occupancy: Shows if you have the right staffing levels",body:"Example: 85 percent occupancy"},{title:"Contacts in queue: Indicates current demand and potential wait times",body:"Example: 15 contacts waiting in the technical support queue"}]},{type:"p",text:"When looking at these metrics, consider them together rather than in isolation."},{type:"p",text:"For example, a high abandonment rate with high average handle time might indicate agents prioritize thoroughness over efficiency. They deeply engage with each customer, causing others to wait longer and potentially abandon calls. A low abandonment with low handle time could suggest agents rush through interactions. They process customers quickly rather than solving issues completely. This reduces wait times and abandonments but might sacrifice service quality."}]}],reviewQuestions:[]},{id:"connect-architecture-fundamentals-t22",number:22,title:"Knowledge Check",shortTitle:"Knowledge Check",summary:"Course content.",duration:"~2 min",lede:null,objectives:[],sections:[],reviewQuestions:[{id:"connect-architecture-fundamentals-t22-q1",question:"A retail contact center manager needs up-to-the-minute information about current call volume and agent status. Which Amazon Connect reporting option provides data that updates every 15 seconds?",options:[{id:"A",text:"Historical metrics report"},{id:"B",text:"Real-time metrics report"},{id:"C",text:"Contact search"},{id:"D",text:"Dashboards and reports"}],correctOptionId:"B",rationale:"Contact search helps locate specific past customer conversations but doesn't deliver real-time updates about ongoing contact center operations. It focuses on historical records rather than current activity tracking."},{id:"connect-architecture-fundamentals-t22-q2",question:"A company's executive team has requested a weekly report on contact center efficiency. Which set of Amazon Connect metrics would provide the most comprehensive view of overall contact center performance?",options:[{id:"A",text:"Occupancy rate, after contact work time, agent on contact time, schedule adherence"},{id:"B",text:"Service level, average handle time, contact abandonment rate, agent productivity"},{id:"C",text:"Contacts handled, average speed of answer, longest queue time, cost per contact"},{id:"D",text:"Contact volume, average queue time, agent schedule adherence, customer satisfaction score"}],correctOptionId:"B",rationale:"This set of metrics provides a balanced view of contact center performance across multiple dimensions. Service level measures how quickly contacts are answered against targets. Average handle time shows efficiency of resolution. Abandonment rate indicates customer patience and staffing adequacy. Agent productivity shows workforce utilization."},{id:"connect-architecture-fundamentals-t22-q3",question:"A contact center supervisor notices that customer satisfaction scores are declining and wants to identify potential causes. Which metrics should the supervisor analyze to determine if customers are waiting too long to speak with agents? (Select TWO.) (Select all that apply: Abandonment rate / Average handle time / Occupancy / Service level / First contact resolution)",options:[],answer:"Abandonment rate; Service level. Average handle time measures how long agents spend with customers after connection, not wait times. Occupancy indicates staffing efficiency but does not directly measure customer wait experience. First contact resolution measures issue resolution effectiveness, not wait times. To determine if customers are waiting too long, abandonment rate and service level provide the most relevant data."}]},{id:"connect-architecture-fundamentals-t23",number:23,title:"Summary",shortTitle:"Summary",summary:"In this section, you learned about reporting and metrics in Amazon Connect provide essential insights for optimizing contact center performance.…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-architecture-fundamentals-t23-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"In this section, you learned about reporting and metrics in Amazon Connect provide essential insights for optimizing contact center performance. Key metrics like abandonment rate, average handle time, and occupancy help managers make data-driven decisions."},{type:"p",text:"By carefully analyzing these metrics, businesses can identify agent training opportunities, improve customer experiences, and allocate resources effectively. Use the customizable reporting tools in Amazon Connect to focus on metrics that align with your specific business goals."}]}],reviewQuestions:[]}],quiz:null};export{e as course};
